"""Domain objects."""


class Customer:
    def __init__(self, name):
        self.name = name


class PurchaseOrder:
    def __init__(self, customer, lines):
        self.customer = customer
        self.lines = lines

    def total(self):
        return sum(price for _, price in self.lines)

"""CSV export."""

from src.store.models import PurchaseOrder
from src.store.pricing import line_total


def to_csv(orders: list[PurchaseOrder]):
    rows = ["customer,lines,total"]
    for order in orders:
        biggest = max((line_total(line) for line in order.lines), default=0)
        rows.append(f"{order.customer.name},{len(order.lines)},{order.total()},{biggest}")
    return "\n".join(rows)

